import NextAuth from 'next-auth';
import CredentialsProvider from 'next-auth/providers/credentials';
import { getQuestion } from './lib/db/questions';

export const {auth, handlers, signIn, signOut} = NextAuth({
    session: {
        strategy: 'jwt',
        maxAge: 60 * 5, // 5 minutes
    },
    providers: [
        CredentialsProvider({
            authorize: async (credentials) => {
                if (!credentials) {
                    return null; 
                }

                let user = null;
                const encryptor = new SubtleCrypto();
                const hashedAnswer = await encryptor.encrypt(credentials.password);
                
                const question = await getQuestion(credentials.username);
                const answer = credentials.password;

                if(answer === hashedAnswer) {
                    user = question;
                    return user; 
                } else {
                    throw new Error('Invalid answer'); 
                }
            }
        })
    ]
});